/**
 * Pre-projected world geometry for the country choropleth (#1797).
 *
 * Generated by `scripts/geo/build-world-countries.mjs` from Natural Earth
 * 4.1.0 admin-0 countries (public domain) via world-atlas 2.0.2 (ISC), in the
 * Equal Earth projection. It is about 87 KB raw / 30 KB gzip and is loaded
 * with a dynamic import, so it is a hashed, immutable chunk that only the
 * country map route ever fetches.
 */

export interface WorldCountryShape {
  /** ISO 3166-1 numeric code, 3 digits. */
  id: string
  /** Natural Earth's short name, used only when no club row names it. */
  name: string
  /** SVG path data in the projected space. */
  d: string
  /** Projected bounding box [x0, y0, x1, y1]. */
  b: number[]
}

export interface WorldMarker {
  id: string
  name: string
  x: number
  y: number
}

export interface WorldGeometry {
  source: string
  width: number
  height: number
  /** The outline of the globe in this projection (the sea). */
  sphere: string
  countries: WorldCountryShape[]
  /** Territories too small for a 1:110m shape, drawn as dots. */
  markers: WorldMarker[]
}

let pending: Promise<WorldGeometry> | null = null

/** Load the geometry once per session; later calls share the same promise. */
export function loadWorldGeometry(): Promise<WorldGeometry> {
  pending ??= import('../../assets/geo/world-countries.json')
    .then(m => (m.default ?? m) as WorldGeometry)
    .catch(err => {
      pending = null
      throw err
    })
  return pending
}
